sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        var operation = current.operation().toUpperCase();
        // new x_boar_bofa_usem_1.BOA_SI_USEMOutboundOutboxWriter().enqueue(current, operation); // previous build (table based batching call);
		var payload = JSON.stringify(new x_boar_bofa_usem_1.BOA_SI_USEM_RemediationTaskPayloadBuilder().buildPayload(current, operation));
		// need to put down script for payload validation
		gs.addInfoMessage(payload)

		new x_boar_bofa_usem_1.BOFA_SI_KafkaProducerV2().sendPayload(payload, current);

    } catch (ex) {
        gs.error(
            '[Mihir USEM Outbound][VUL] Failed for {0}:{1}. Error: {2}',
            [current.getTableName(), current.getUniqueValue(),
                ex.message || ex
            ]
        );
    }


})(current, previous);
